contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(uint arg) public payable {
        require(true);
        uint balBefore = address(c).balance;
        bool reverted;
        c.Initialized(); bool __rev0 = __ESBMC_reverted(); if (__rev0) { reverted = true; } else { reverted = false; }
        uint balAfter = address(c).balance;
        assert(balAfter == balBefore);
    }
    receive() external payable {}
}

